    "code": "mkdir -p nps-output && python3 -c '
import subprocess, re

res = subprocess.run([\"python3\", \"generate_song.py\"], capture_output=True, text=True)
output = res.stdout + res.stderr
match = re.search(r\"RESULT_OK:(https?://[^\\s]+)\", output)
if match:
    url = match.group(1)
    print(f\"URL trouvée : {url}\")
    subprocess.run([\"curl\", \"-L\", \"--fail\", \"--show-error\", url, \"-o\", \"nps-output/petit_matin.mp3\"])
else:
    print(\"Erreur de génération ou URL introuvable dans la sortie :\")
    print(output)
    exit(1)
' && test -s nps-output/petit_matin.mp3 && stat -c '%n %s bytes' nps-output/petit_matin.mp3
